(function () {
  function normalizeUrl(url) {
    return String(url || '').replace(/\/+$/, '');
  }

  function parseResponse(response) {
    if (!response.ok) {
      return response.text().then((text) => ({
        data: null,
        count: null,
        error: {
          message: text || response.statusText,
          status: response.status
        }
      }));
    }

    const contentRange = response.headers.get('content-range');
    const count = contentRange && contentRange.includes('/')
      ? Number(contentRange.split('/').pop())
      : null;

    if (response.status === 204 || response.headers.get('content-length') === '0') {
      return Promise.resolve({ data: null, count, error: null });
    }

    return response.text().then((text) => ({
      data: text ? JSON.parse(text) : null,
      count,
      error: null
    }));
  }

  function createClient(url, key) {
    const baseUrl = normalizeUrl(url);
    const headers = {
      apikey: key,
      Authorization: `Bearer ${key}`
    };

    return {
      rpc(functionName, params) {
        return fetch(`${baseUrl}/rest/v1/rpc/${encodeURIComponent(functionName)}`, {
          method: 'POST',
          headers: {
            ...headers,
            'Content-Type': 'application/json'
          },
          body: JSON.stringify(params || {})
        }).then(parseResponse).catch((error) => ({ data: null, error }));
      },

      from(tableName) {
        const tableUrl = `${baseUrl}/rest/v1/${encodeURIComponent(tableName)}`;

        return {
          delete() {
            return {
              not(column, operator, value) {
                const params = new URLSearchParams();
                params.set(column, `not.${operator}.${value}`);
                return fetch(`${tableUrl}?${params.toString()}`, {
                  method: 'DELETE',
                  headers: {
                    ...headers,
                    Prefer: 'return=minimal'
                  }
                }).then(parseResponse).catch((error) => ({ data: null, error }));
              }
            };
          },

          insert(rows) {
            return fetch(tableUrl, {
              method: 'POST',
              headers: {
                ...headers,
                'Content-Type': 'application/json',
                Prefer: 'return=minimal'
              },
              body: JSON.stringify(rows)
            }).then(parseResponse).catch((error) => ({ data: null, error }));
          },

          select(columns, options) {
            const params = new URLSearchParams();
            params.set('select', columns || '*');
            const wantsHead = options && options.head;
            const wantsCount = options && options.count;
            return fetch(`${tableUrl}?${params.toString()}`, {
              method: wantsHead ? 'HEAD' : 'GET',
              headers: {
                ...headers,
                Prefer: wantsCount ? `count=${wantsCount}` : ''
              }
            }).then(parseResponse).catch((error) => ({ data: null, count: null, error }));
          }
        };
      }
    };
  }

  window.supabase = { createClient };
})();
